CREATE TABLE IF NOT EXISTS memberships(user_id TEXT NOT NULL,server_a_id TEXT NOT NULL,server_b_id TEXT NOT NULL,role_id TEXT NOT NULL,purchase_reference TEXT,expires_at TEXT,last_role_check_at TEXT,last_role_status TEXT NOT NULL DEFAULT 'unknown' CHECK(last_role_status IN('active','missing','unknown')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','expired_pending_check','renewal_required','offboarded','verification_error')),active_ticket_id INTEGER,last_offboarded_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,server_a_id));
CREATE INDEX IF NOT EXISTS idx_expiry ON memberships(expires_at,status);
CREATE TABLE IF NOT EXISTS renewal_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,server_a_id TEXT NOT NULL,channel_id TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')),created_at TEXT DEFAULT CURRENT_TIMESTAMP,closed_at TEXT,closure_reason TEXT,FOREIGN KEY(user_id,server_a_id) REFERENCES memberships(user_id,server_a_id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,source_guild_id TEXT NOT NULL,destination_guild_id TEXT,action_type TEXT NOT NULL,target_user_id TEXT,executor_user_id TEXT,role_id TEXT,reason TEXT,event_timestamp TEXT NOT NULL,details_json TEXT);
CREATE TABLE IF NOT EXISTS job_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,job_name TEXT NOT NULL,user_id TEXT,started_at TEXT DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,result TEXT DEFAULT 'retry',error_message TEXT);
